import{_ as t,c as a,o as e,ae as o}from"./chunks/framework.BvcDoAct.js";const N=JSON.parse('{"title":"02 SHUNTO 的故事","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/2_SHUNTO/2_edited.md","filePath":"scripts/output/2_SHUNTO/2_edited.md"}'),S={name:"scripts/output/2_SHUNTO/2_edited.md"};function T(s,p,r,n,i,c){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="_02-shunto-的故事" tabindex="-1">02 SHUNTO 的故事 <a class="header-anchor" href="#_02-shunto-的故事" aria-label="Permalink to &quot;02 SHUNTO 的故事&quot;">​</a></h1><h2 id="强烈的意志、开阔的视野、丰沛的表达力。在音乐中与人相连并绽放的天赋轨迹" tabindex="-1">强烈的意志、开阔的视野、丰沛的表达力。在音乐中与人相连并绽放的天赋轨迹 <a class="header-anchor" href="#强烈的意志、开阔的视野、丰沛的表达力。在音乐中与人相连并绽放的天赋轨迹" aria-label="Permalink to &quot;强烈的意志、开阔的视野、丰沛的表达力。在音乐中与人相连并绽放的天赋轨迹&quot;">​</a></h2><p>● 听这张精选专辑，果然还是会感到时间在流动啊。</p><p>「感受特别强烈。现在我们刚进入第 5 年。换个角度想，才会重新意识到：我们其实是用很短的间隔一直在发歌。看到精选里收了 3 首新录，我还会想，『我们有录过 3 首这么多吗？』」</p><p>● 但实际上你们都已经出了 2 张专辑了，可不止 3 首（笑）。</p><p>「是啊（笑）。不过我们真的是一首一首认真做过来的，这点从歌声里也听得出来。我也会想起，每做完 1 首，我们就会找到下一首要衔接的课题。现在回头看，会觉得一直保持那种姿态是对的。」</p><p>● 每位成员的变化和成长都被刻进了作品里。那 SHUNTO，你自己的变化呢？</p><p>「我感觉自己内在的艺术性和态度感，是每过一个阶段就会更强一点。最开始我只能照着给到的指导去做，但从前一阵子开始，我的意见也能被纳入了。像『我觉得这样卡进去会更舒服』这种话，现在也能说出来不少。我觉得这可能是我变化最大的地方。还有一个原因，可能是作为 BE:FIRST 的根基变强了，所以我也更有自信了。」</p><p>● 这是有某个契机吗？</p><p>「从出道初期开始，我就一直会玩着做歌。那并不是以『我要做 solo』为目标，而是我心里一直有个前提：既然是团体活动，什么都有可能发生。所以我从一开始就一直在做，倒不是为了马上发出来——」</p><p>● 也就是说，团体是团体，同时你也一直在打磨自己的创造力。</p><p>「对。我读书也不行，要是哪天不能留在团里了，我可能就什么都做不了了。所以我一直觉得，音乐方面的知识哪怕一点点也要增加。那种积累，大概是从《Mainstream》前后开始显出来了。」</p><p>● 的确，从那个时期开始，会觉得 SHUNTO 的存在感和表演又上了一个台阶。</p><p>「真的吗？我自己其实不太知道……不过我确实开始认真学音乐文化，也会在这个基础上去听歌。也许就是从这些地方慢慢变了。从《Mainstream》那时候开始，我有一点『自己的风格』和『在团里的角色定位』终于完全卡上的感觉。虽然我也不是说当时就有多深入地去想这些。」</p><p>● 那在那之前，你是怎么理解自己在团体里的位置的？</p><p>「其实我已经不太记得了，但我觉得那时候大家都挺可爱的（笑）。每个人都想被看见、都想站到最前面，大家都在冲中心位。我自己也是。现在就不是那种感觉了。」</p><p>● 在 2022 年的个人采访里，SHUNTO 你说过：**「重要的是，你能想象每个人的人生到什么程度。」**你当时说，在尊重彼此人生的前提下，每个人都以本来的样子存在很重要。</p><p>「是的。」</p><p>● 我觉得这份心情你现在也没变。不过你在团体内部对「平衡」这件事，好像也更能从整体视角去看了。</p><p>「是。我自己的情况，可能也跟年龄很直接有关。那时候还是十几岁，现在 22 岁了，可能就是慢慢在变成大人吧（笑）。人长大以后，会长出一种『好的意义上的放下』。我感觉自己这部分变得很明显。」</p><p>● 也就是会「知道分寸」，会更理解很多事了。</p><p>「对。包括环境，还有很多别的因素在内。」</p><p>● 我到现在都记得，2022 年 BE:FIRST 第一次登上 ROCK IN JAPAN FESTIVAL 的舞台时，我当时就觉得「SHUNTO 觉醒了」。</p><p>「好怀念啊。」</p><blockquote><p>我内在的艺术性和态度感，是每经历一个阶段就会更强一点。作为 BE:FIRST 的根基变强了，也让我更有自信。</p></blockquote><p>● 我觉得从那时到现在是一条连起来的线。回头看，当时你的自我表达好像更外放；但现在是力量更强了，视野却更开了，有种冷静控制住它的感觉。</p><p>「确实，那时候就是一股猛劲往前冲。但现在我会觉得，强烈的自我表达如果不能控制住，就没有意义。像巡演里每次都唱同一套歌单编排（Setlist），人会不知不觉变得习惯；可我们从一开始就很重视『每一场演出都要像第一次』。也因为一直这样累积下来，我现在慢慢更懂了：在什么场合、用什么热度、在什么时机做什么，观众才会真正被带起来。我也觉得，这种东西如果不能控制，就走不长。」</p><p>● 也就是站在来看演出的人那一侧去思考。</p><p>「对。现在回头看，最近 MC 里想说的话会很自然地出来，但以前我会想到半夜都睡不着。比如某个措辞配某种说法，会不会被那样理解……这种事我会一直想，记下来，又删掉，反复来回。」</p><p>● 你为什么会在意到那个程度？</p><p>「有一部分是我不希望别人不舒服，也不想被误解；但归根结底，最大原因还是不熟练。成员里很多人都能很顺地一直讲，JUNON 和我就属于不太会讲话的类型，所以我也会有『得赶快跟上』的心情。而且我经常会被交给比较重要的 MC 段，压力真的很大。」</p><p>● 对 SHUNTO 来说，「有人愿意接住你们的音乐表演」这件事应该非常重要。你面对这件事的立场和方式，随着活动累积有变化吗？</p><p>「核心没变。那份心意没有变。只是我越来越觉得，表达它的方法有很多种，所以我想把这方面的想象力再丰富、再强化一些。比如演出现场有很大的屏幕，我觉得它也能传达很多东西，所以怎么用它很关键。反过来，有时候故意不去理它，反而会很帅。我也想把这些都分析清楚。」</p><p>● 也就是说，一方面你会非常冷静地思考你们的表演和存在方式，另一方面该释放的部分也会释放，这个平衡变得更好了。</p><p>「我也感觉，演出时自己越来越能不硬撑着发力了。」</p><p>● 你以前采访里还说过：**「不束缚自己，想做的事就要有野心地去做，这是我个人的规则。」**这条规则和「去想对方要什么、此刻做什么才是对的」看起来像是反方向，但在你这里并不矛盾。</p><p>「我觉得全都是平衡，而且那也会连到体谅和温柔上。那不是让人难受的矛盾。正因为能好好混在一起、维持好的平衡，人才能称作人吧。反而在情绪复杂的时候，我会更觉得人很有意思。我自己也是，一边想有野心地去做想做的事，一边也在追求稳定。我觉得一定程度的日常节奏是必要的，而能长期维持它本来就难。这也是平衡：一部分要一直保持自律地做下去，另一部分偶尔做点不一样的，给自己刺激。」</p><p>● SHUNTO 你应该经常被周围人说「你很自律吧」。你怎么看别人这样看你？</p><p>「我其实不算自律。只是我这个人特别怕麻烦。但我不喜欢拿『麻烦』当借口就不做。偶尔休息可以，可要是把『麻烦』当理由，我会觉得『你到底在想什么』。我只是不想变成那样的人而已。」</p><p>● 这在别人眼里，可能就会显得很自律。</p><p>「是这样吗。」</p><p>● 这话不太好说，但对我来说，BE:FIRST 里台上台下反差最大的就是 SHUNTO。比如 LEO 在台上台下都还是那个 LEO，SOTA 也是。但 SHUNTO 会让我觉得，站在舞台上和下了舞台像是两个人。</p><p>「原来如此。现在其实没以前那么明显了，不过我本来就不太有自信，所以我会很憧憬那种状态。像 LEO 或 SOTA 那样，不管什么时候都能做自己、做自己的音乐，那真的很棒。我自己会很容易害羞。因为我是带着不够自信的状态长大的，所以可能真的需要一个『开关』，不按下去就很难带着自信去表演。」</p><p>● 「原本的自己」「自由」「Be Myself」这些词，每个人理解都不同。对 SHUNTO 来说，连这个开关的开与关都算在内，你正在更能把「原本的自己」活出来。</p><p>「嗯，我也有这种感觉。」</p><p>● 说回最开始，刚成为 BE:FIRST 的时候，你有过「想变成什么样」的理想形象吗？</p><p>「嗯……在成为 BE:FIRST 之前，我很想变成 AAA 那样。所以我特别憧憬 Nissy。但出道之后，我好像不会再去特别憧憬某一个人了。更像是吸收各种人身上的优点，同时去找自己的风格。一直以进化为目标的话，我觉得只要进化的方向里有一贯性就可以了。那样它自然会长成我自己的风格。」</p><p>● 你说的这个「一贯性」，你觉得是什么？你到底在朝哪里奔跑？</p><p>「我到底在朝哪里跑……这题很难。」</p><p>● 我们做 BMSG 5 周年特集采访时（《rockin&#39;on JAPAN》2025 年 12 月号），你提到「社长最近常说『大家一起变幸福吧』」。但「幸福」本身有很多层含义。对 SHUNTO 来说，什么状态可以叫作「幸福」？</p><p>「不知道（笑）。当然，和大家一起吃饭的时候会很开心……也许是『不后悔』吧。没有后悔的人生很难，所以我会想，如果最后能笑着说『真有意思啊』，那样的人生就很好。」</p><blockquote><p>我是一边吸收各种人的优点，一边找自己的风格。始终以进化为目标的话，只要进化方向里有一贯性就好了。</p></blockquote><p>● 明白。或者说，大约 3 年前第一轮巡演《BE:FIRST 1st One Man Tour “BE:1” 2022-2023》结束时，你说过「我变得能开心地唱歌了」。你当时的意思是「原来为别人而唱，会涌出这么强的力量」。那现在的 SHUNTO，在做音乐时「开心」的感觉在哪里？</p><p>「我觉得最开心的，就是在演出里感到一体感、和台下来回接球的瞬间。最早那阵子，很多歌都是随着演出一场场变得更好，我也常能感觉到那种接球感。最近的话，我有一种『把我们这一代常听的音乐，作为 BE:FIRST 来做出来』的感觉。通过这种歌去和观众接触、和音乐接触的时间，我会觉得很开心。做歌的时候，或者通过音乐和人连起来的瞬间，我都特别开心，也会感到幸福……虽然说出来有点害羞（笑）。」</p><p>● 也有人是那种「只要埋头做东西就很快乐」的类型。比如把自己想象的东西做成形会快乐，做出新表达也会快乐。但 SHUNTO 的情况是，在这之外，还需要有「接收的人」在，才会感到那份快乐。</p><p>「当然，发现新的自己，我也会觉得开心。」</p><p>● 这次你们把《I Want You Back》作为精选专辑新录曲来翻唱。这首歌连声音质感在内，都是过去 BE:FIRST 没有过的类型，而且原曲本身是超级名曲、体量也非常大。做这首歌，你觉得快乐点在哪里？</p><p>「这个就纯粹是好玩、纯粹开心。我们在对盘演出时也偶尔会唱，唱别人的歌放在自己的舞台上，真的特别开心。可能因为那不是平时常唱的歌，也可能因为它本来就是我们平时会听的音乐。所以像电视录制里唱《I Want You Back》的时候，我也有种很不可思议的感觉。比起紧张或『会不会跳错』，我更多是觉得：原来我们在自己的舞台上唱这首歌啊，太开心了。而且这首歌本身就很快乐。唱自己的歌时，每一次录制都会有那种『这就是一战』的气氛，但《I Want You Back》不太一样。当然，也有『我们能被允许唱这首歌』那种意义上的紧张，但整体还是非常开心。」</p><p>● 比起「要传达某种讯息」，你更能把焦点放在「享受音乐」上。</p><p>「对。录音也很开心。要怎么在演唱里放进敬意，我们会和社长一起边想边录。那个指导也很有意思。」</p><p>● BE:FIRST 每首歌呈现出来的表情都不一样。尤其 SHUNTO 的声音振幅很大，这是你的魅力之一。但《I Want You Back》这次的声线很自然。</p><p>「确实。虽然我最后一个 Hook 算是例外，但整体来说，这首歌的 Key 应该是男性比较好唱的。所以如果你想在 KTV 唱《I Want You Back》，请一定唱我们这个版本。毕竟是日语（笑）。」</p><p>● 虽然是日语，但是 Rap 啊。</p><p>「（笑）Rap 的部分我们也是在不丢原曲优点的前提下，做成 BE:FIRST 的样子。所以如果能听出我们很本真的状态，我会很开心。超越过去作品里的自己，这一点没有变；同时也没有硬绷着，录音时间也跟平常一样结束。整体有一种很中性地完成它的感觉。」</p><p>● 能够这么中性地面对这首歌，本身也是 BE:FIRST 一路累积到现在的成果。</p><p>「都进入第 5 年了啊。说真的，我们居然已经做了 4 年，我自己也没什么实感。要是看年表，看到『这一年发生了这个那个』，大概会觉得『确实做了 4 年』。但体感上真的很快。所以我想，应该是我们一直很努力吧（笑）。」</p><p>● 我觉得这是你们为了把计划和愿景真正落地，持续投入能量的 4 年。</p><p>「那太好了。我是那种睡一觉就会忘的人（笑）。如果什么都一直往心里压，可能早就被甩在后面了。」</p><p>● 不过经验变多以后，光靠一股猛劲往前冲，肯定会有行不通的地方。你现在对前进方式、以及之后的路，是怎么想的？</p><p>「会议变得很多。我们会在里面做磨合，把我们想做的事和厂牌、公司的意见对齐。既会清楚表达『这里我们就是不想让』，也会说『请给我们一点休息时间』这种话（笑）。」</p><p>● 哈哈哈哈！</p><p>「会说『拜托，这里至少要守住！』那种（笑）。我觉得我们就是这样在稳稳往前走。」</p><p>● 不管是创作层面还是其他方面，成员各自有想法，厂牌和公司也有各自视角，所以不可能所有立场一次就对齐。遇到这种情况，SHUNTO 会用什么立场？</p><p>「不想让的地方一定会说，这点没变。但就算这样，也会有不得不接受的意见。那种时候我就会回房间写 Rap（笑）。有点烦躁的东西，我会自己写进歌词里。」</p><p>● 你会在那边把它消化掉。这个真的很重要。</p><p>「对。我会觉得『我这做法也太健康了吧』（笑）。而且很意外，反而这种时候更容易冒出有意思的表达。」</p><p>● 那你不会想把这些内容以 BE:FIRST 或 solo 的形式发到外面吗？</p><p>「目前还不会。以后有一天会想做吧。」</p><p>● 也就是说，你会很冷静地判断：现在作为 BE:FIRST 应该做什么。</p><p>「对，这块我会分开来想。」</p><p>● 在进入第 5 年的节点推出精选专辑。按我的理解，到这里算是 BE:FIRST 的第一章。再往后的 5 年、10 年会怎样，我觉得会比现在更需要每位成员作为创作者的那一面。</p><p>「嗯。」</p><p>● 那会变成团体新的力量。不只 SHUNTO，每个人如何把各自的创作力反哺进 BE:FIRST，我都很期待。</p><p>「我很想做合宿。联合创作（co-write）合宿。个人上特别想做，自己一个人也行。」</p><p>● 不和成员一起吗？</p><p>「也不是……跟大家一起也可以，但大家都来了好像会很吵（笑）。人一聚齐可能就会开始跳舞。我想做的不是那个，是只做联合创作的合宿。想让自己能带着真正的见识去做音乐。以后就算我去参与联合创作，也得成为那种会被说『因为有这个人，这首歌才会变成这样』的人。」</p><p>● 真做到那样，就会成为世界上罕见的男团了。为此也请你一定保重身体，继续加油。</p><p>「我会的。我真的特别容易感冒。其实『BMSG FES&#39;25』那时候我就发烧了，最近又发烧一次，感觉不太妙。只要一段时间连续都是需要绷紧神经的工作，我就很容易在排练阶段把身体搞垮。」</p><p>● 稍微一松下来就会一下子找上来。</p><p>「是啊。不过我最近已经连续发过烧了，所以现在应该已经有抗体了。接下来一阵子应该没事（笑）。」</p>',90)])])}const O=t(S,[["render",T]]);export{N as __pageData,O as default};
